"""Assemble the preprint narrative with counts from the saved analysis tables."""
from pathlib import Path
import csv,json,collections
ROOT=Path(__file__).resolve().parents[1]
def read(name):return list(csv.DictReader((ROOT/'tables'/f'{name}.csv').open(encoding='utf-8-sig')))
def pct(n,N):return f'{100*n/N:.1f}'.replace('.',',')+'%' if N else 'не определено'
def num(x,d=2):return f'{float(x):.{d}f}'.replace('.',',') if x not in ['',None] else 'не определена'
def main():
    facts=json.loads((ROOT/'tables/key_results.json').read_text(encoding='utf-8'))
    meta_path=ROOT/'data/corpus.json'
    if not meta_path.exists():meta_path=ROOT/'data/corpus_metadata.json'
    meta=json.loads(meta_path.read_text(encoding='utf-8'))
    annotations=json.loads((ROOT/'data/annotations_final.json').read_text(encoding='utf-8'))
    indexed={x['id']:x for x in annotations};m={x['id']:x for x in meta}
    profiles=read('profiles');agreement=read('ai_agreement');sense=read('sensitivity')
    names={'telegram_post':'Telegram: посты','pikabu_post':'Пикабу: посты','pikabu_comment':'Пикабу: комментарии','tabiturient_question':'Табитуриент: вопросы','tabiturient_answer':'Табитуриент: ответы'}
    def stat(group,code):
        x=next(x for x in profiles if x['group']==group and x['code']==code)
        return f"{x['n']}/{x['N']} ({num(x['pct'],1)}%)"
    def agree(group,code):return next(x for x in agreement if x['group']==group and x['code']==code)
    blocks=[]
    def p(s):blocks.append({'type':'p','text':s})
    def h(i,s):blocks.append({'type':'h2','id':i,'text':s})
    def table(headers,rows):blocks.append({'type':'table','headers':headers,'rows':rows})
    def fig(stem,caption):blocks.append({'type':'figure','file':stem,'caption':caption,'alt':caption})
    p('В сохранённом корпусе обнаружены разные способы обоснования образовательных траекторий, но оснований считать механизм охлаждения доказанным пока нет. Эта версия представляет разведочный анализ автоматической разметки: она показывает доступные случаи, ограничения наблюдения и точки, требующие проверки исследователем. Частоты описывают решения моделей по собранным текстам, а не распространённость установок среди населения.')
    p('Разметка исследователем, контроль согласия исследователя и модели, повторная разметка исследователем через две недели и проверка переноса правил на отложенные периоды или организации НЕ проведены. Они перенесены на подготовку основной публикации. Выполненные ниже модельные проверки не заменяют эти процедуры. До завершения этих проверок выводы имеют разведочный статус.')
    h('scope','Материал, единицы и границы сравнения')
    p('Анализ опирается на METHODOLOGY.md версии 2.2 и готовый литературный обзор. В действующей методологии сформулированы пять исследовательских вопросов ВИ1–ВИ5; они не превращаются здесь в заранее подтверждённые статистические гипотезы. Использован один сохранённый экспорт stage1: 1 094 записи в 723 родительских пакетах — 420 официальных постов Telegram, 174 поста Пикабу с 166 сохранёнными комментариями и 129 вопросов Табитуриента с 205 ответами. Отдельный массив stage1/data/full не присоединялся.')
    p('Скрининг включил '+str(facts['included_total'])+' сообщения. Нерелевантные материалы и записи с недостаточным текстом отделены; наличие охлаждения или критики образования не служило условием включения. Единица количественного подсчёта — сообщение определённого типа; контекстная единица — родительский пост или вопрос с сохранёнными дочерними сообщениями. Несколько ответов одному вопросу не являются независимыми наблюдениями людей. Все таблицы содержат отдельные знаменатели для пяти типов сообщений; совместимые коды могут давать сумму свыше 100%.')
    table(['Тип сообщения','Собрано','Включено','Исключено','Недостаточно данных'],[[names[x['group']],x['total'],x['included'],x['excluded'],x['undetermined']] for x in facts['screening']])
    fig('01_screening','Рисунок 1. Скрининг корпуса по типам сообщений. Неопределимость отделена от отсутствия исследуемого признака.')
    p('Telegram представлен выборками из фиксированных окон, а не непрерывным потоком: 240 постов Минобрнауки и 180 постов Минпросвещения. Для сравнения ведомств использованы только общие июльские окна 2022–2026 годов. В Пикабу сохранён обычно один комментарий к посту: 166 из 174 постов имеют такой комментарий; полных веток обсуждения в данных нет. В Табитуриенте ответы сохранены для 95 из 129 вопросов. 122 вопроса отобраны по случайным ID, ещё 7 — целенаправленно; последним соответствуют 13 записей вместе с ответами. Это не случайная выборка всех российских абитуриентов.')
    p('Календарные интервалы следуют методологии: до 11.03.2020; 11.03.2020–23.02.2022; 24.02.2022–31.12.2023; 2024–06.10.2026. Для Пикабу два последних интервала объединены по правилу доступности: в третьем интервале только 15 включённых родительских постов. Для остальных корпусов объединение не понадобилось. Различная длина интервалов, окна отбора и неполные обсуждения не позволяют трактовать частоты как динамику общественного мнения или эффект реформ.')
    fig('07_calendar_coverage','Рисунок 2. Календарное покрытие до скрининга. Отсутствие записей в ячейке означает отсутствие материала в сохранённом экспорте.')
    h('coding','Кодирование и фактические результаты контроля')
    p('Предварительный кодификатор v1.1 создан на основе методологии и уточнён на модельном пилоте из 24 контекстных пакетов (45 сообщений). Три агента GPT-6 Luna с уровнем рассуждения medium прочитали тексты по отдельным корпусам и сохранили индивидуальные решения. Тексты передавались с автоматической маскировкой части прямых идентификаторов; такая обработка не гарантирует полной анонимности. В этом публичном изложении пользовательские эпизоды перефразированы. Полные тексты, точные опорные фрагменты и таблица исходных ссылок остаются служебными файлами.')
    p('Для дополнительного контроля случайно выделены по 30 пакетов каждого корпуса вне пилота, всего 90 пакетов и 165 сообщений. Их повторно размечал другой агент той же модели без просмотра первой разметки; распределение корпусов между агентами было циклическим. Этот контроль составляет около 15% сообщений и не соответствует предусмотренной методологией человеческой контрольной процедуре с её правилом 20% и минимумом 30 единиц. Общая модель и общий кодификатор могут воспроизводить одинаковые ошибки.')
    p('Согласие рассчитано по исходным решениям до содержательного согласования. Скрининг сравнивается на всех контрольных сообщениях, остальные коды — только там, где обе разметки включили сообщение; этот отбор явно отражён числом пар. Неопределимые значения исключены попарно; таблица показывает фактическое число сопоставленных пар. Для номинальных категорий вычислена номинальная альфа Криппендорфа, для степени речевого недовольства — порядковая. Это согласие «модель–модель», не оценка правильности и не согласие человека с моделью. Если обе разметки дают только одну категорию, альфа не определена даже при 100% совпадений. Precision, recall и F1 относительно исследователя не рассчитывались: эталонной разметки нет.')
    chosen=[('telegram_post','r','Релевантность'),('telegram_post','l_rat','Практическая польза'),('pikabu_post','r','Релевантность'),('pikabu_post','l_narr','Истории успеха/неудачи'),('pikabu_comment','r','Релевантность'),('pikabu_comment','rd','Прочтение тезиса'),('tabiturient_answer','l_rat','Практическая польза'),('tabiturient_answer','m_warm','Поддержка ожиданий'),('tabiturient_answer','m_route','Сохранение цели при смене пути'),('tabiturient_answer','rd','Прочтение тезиса')]
    table(['Тип','Код','Пар','Совпадение','Альфа, модель–модель'],[[names[g],label,agree(g,c)['n_pairs'],pct(float(agree(g,c)['agreement']),1) if agree(g,c)['agreement'] else 'н/д',num(agree(g,c)['alpha'])] for g,c,label in chosen])
    p('Контроль выявил существенную зависимость ряда результатов от кодировщика. Например, альфа практической аргументации в Telegram равна '+num(agree('telegram_post','l_rat')['alpha'])+', поддержки ожиданий в ответах Табитуриента — '+num(agree('tabiturient_answer','m_warm')['alpha'])+', сохранения цели при смене пути — '+num(agree('tabiturient_answer','m_route')['alpha'])+', прочтения тезиса — '+num(agree('tabiturient_answer','rd')['alpha'])+'. Следовательно, эти частоты нельзя представлять как надёжно установленные количественные различия. Ниже они оставлены как прозрачное описание предварительной разметки и основание для выбора случаев; содержательные обобщения по нестабильным кодам отложены.')
    n_adj=len(json.loads((ROOT/'audit/model_adjudications.json').read_text(encoding='utf-8')))
    p(f'После первичной разметки ведущий ИИ-ассистент рассмотрел пограничные случаи и отдельно зарегистрировал {n_adj} содержательных поправок. Они не заменяют человеческой проверки и не используются для улучшения показателей согласия задним числом. Исходные решения, изменения и сравнение частот до/после сохранены. Отбор подробно обсуждаемых эпизодов выполнен после получения кодов; его нельзя называть предварительной регистрацией качественной выборки.')
    h('vi1','ВИ1. Темы и обоснования официальной коммуникации')
    p('Общие июльские окна содержат 73 включённых поста Минпросвещения и 89 постов Минобрнауки. В первой разметке практическая польза присвоена 54/73 (74,0%) и 79/89 (88,8%) сообщений соответственно. Ссылки на авторитет и нормы — 7/73 (9,6%) и 16/89 (18,0%); моральные обоснования — 6/73 и 1/89; истории успеха или неудачи — 4/73 и 2/89. Тема СПО отмечена в 25/73 и 4/89 постов, ВО — в 52/73 и 89/89. Эти темы могут сочетаться в одном тексте.')
    p('Материал позволяет выделить аргументы доступности обучения, профессиональной подготовки и карьерной полезности как направления качественного разбора. Однако слабое модельное согласие по практической аргументации не позволяет утверждать, что одно ведомство достоверно чаще использует этот способ легитимации. Из сравнения также нельзя вывести намерение направить абитуриентов в СПО: для этого необходимо связать конкретное предложение с исходной целью и препятствием в том же эпизоде.')
    fig('02_official_arguments','Рисунок 3. Предварительные модельные частоты способов обоснования в сопоставимых июльских окнах. Разница столбцов не является проверенным эффектом ведомства.')
    h('vi2','ВИ2. Охлаждение, поддержка и сохранение цели')
    p('Строгое охлаждение определялось совместным присутствием явно названной исходной цели, внешнего предложения снизить её из-за препятствия и смягчающего обоснования нового пути. По сохранённой разметке после модельного разбора пограничных эпизодов таких случаев не выделено. Это результат работы с данным корпусом и данным правилом, а не доказательство отсутствия охлаждения в образовательном консультировании: пропуски, короткие ответы и возможные ошибки модели ограничивают обнаружение.')
    p('Из 202 включённых ответов Табитуриента информирование отмечено в '+stat('tabiturient_answer','m_info')+', поддержка ожиданий — в '+stat('tabiturient_answer','m_warm')+', сохранение цели при смене пути — в '+stat('tabiturient_answer','m_route')+'. После модельного пересмотра код сохранения исходной цели g=same имеется у 112 ответов, отсутствие сопоставления целей — у 86, неопределимость отношения к цели — у 4. Ни один окончательный код не фиксирует уверенного снижения цели; в первичной разметке ответов таких меток было четыре. Две относились к критике конкретной программы без предложения изменить цель, ещё две — к описанным ниже пограничным предложениям. Низкое согласие по механизмам ограничивает интерпретацию этих чисел.')
    fig('03_advice_mechanisms','Рисунок 4. Механизмы и наблюдаемость отношения к исходной цели в ответах Табитуриента. Частоты сохраняются для проверки, а не как доказательство преобладания стратегии.')
    p('В эпизоде TB0071–TB0074 родитель сообщает о низких экзаменационных результатах и спрашивает, куда можно поступить. Ответ предлагает колледж или пересдачу экзамена. Однако исходная цель именно высшего образования не названа, а выражение сожаления не равно содержательному оправданию снижения цели. В эпизоде TB0224–TB0225 на запрос об университетской подготовке для работы с данными предложен аграрный техникум без объяснения. Возможная ирония и отсутствие описанного препятствия не позволяют принять ответ за строгий случай охлаждения. Оба эпизода сохранены как пограничные, без такого кода.')
    p('Контрпример автоматическому приравниванию альтернативы к снижению цели даёт пакет TB0289: в ответе TB0294 предложены смежные технические направления и иной способ финансирования с сохранением перспективы работы в IT. Обещания общежития, карьерной помощи или доступности в таких ответах анализируются как речевые аргументы; их фактическая исполнимость не проверялась. Семь ответов имеют исходную метку university_label, но принадлежность автора вузу независимо не удостоверялась. Сравнение стратегий приёмных комиссий вузов и колледжей по этим данным невозможно.')
    p('Для описания контекста вопросы разделены на процедурные и смешанные; включённые ответы распределились между ними как 111 и 91. Предложение альтернативы отмечено соответственно в 60/111 (54,1%) и 65/91 (71,4%) ответов. Это структура модельных меток, не проверка различий поведения консультантов. Вопросы и ответы подавались в общем контекстном пакете с инструкцией кодировать вопрос по его собственному тексту; отдельное техническое ослепление вопроса от ответа не применялось. Это дополнительное отклонение от строгой реализации методологии.')
    h('vi3','ВИ3. Семейный опыт, самоописание и прочтения')
    p('Код семейного опыта как аргумента имеется в 26/134 постов Пикабу, 3/100 комментариев и 2/208 официальных постов. В Табитуриенте этот код в итоговой разметке отсутствует; это не означает отсутствия родителей среди участников: код требует использования семейного опыта в аргументации, а не одного упоминания сына или дочери. Роль автора через самоописание установлена в 95/134 постов Пикабу, 16/100 комментариев, 43/129 вопросов и 17/202 ответов Табитуриента. Профессии и характеристики цитируемых героев не переносились автоматически на автора сообщения.')
    p('Образование родителя прямо установлено лишь в одном включённом сообщении; в остальных 772 случаях оно неизвестно. Сравнение оценок образования между родителями с высшим образованием и без него поэтому невозможно. В кейсе PK0181 автор одновременно описывает родительство, полученное высшее образование и решение освоить ремесленную подготовку. Такой сюжет допускает прочтение СПО как дополнительного профессионального развития, но сам по себе не показывает навязанного снижения цели.')
    p('Теоретические категории доминантного, переговорного и оппозиционного прочтения требуют определимого исходного тезиса. Модель отметила такой тезис в 78/100 комментариев Пикабу, 7/134 постов и только 3/202 ответов Табитуриента. Повторная разметка ответов существенно расходится с первой: согласие по rd '+pct(float(agree('tabiturient_answer','rd')['agreement']),1)+', альфа '+num(agree('tabiturient_answer','rd')['alpha'])+'. Поэтому распределение типов прочтения не используется для вывода о принятии или сопротивлении официальной политике. Прочтение бытового совета также не тождественно прочтению государственного сообщения.')
    fig('04_family_observability','Рисунок 5. Доступность наблюдений для ВИ3. Отсутствие самоописания — пропуск сведений, а не свидетельство отсутствия социальной роли.')
    h('vi4','ВИ4. Аргументы девальвации диплома')
    p('После модельного разбора выделено 9 сообщений с оценкой снижения ценности диплома ВО: 5 постов Пикабу, 3 ответа Табитуриента и 1 официальный пост. До разбора таких меток было 12. Сравнение заработков профессий, критика работы в системе образования и совет выбрать вуз с удобным графиком исключены из этого строгого признака, когда оценка ценности диплома прямо не выражена. Девять случаев не следует трактовать как точную оценку распространённости девальвации: редкий код требует отдельной проверки всех положительных и возможных пропущенных случаев.')
    bases=facts['devaluation_bases']
    p(f'В этих девяти сообщениях представлены трудоустройство ({bases["work"]}), символический статус ({bases["status"]}), навыки и знания ({bases["skills"]}), качество обучения ({bases["quality"]}), доход ({bases["income"]}) и избыток дипломированных выпускников ({bases["inflation"]}). Основания совместимы, поэтому их сумма превышает число сообщений. Профиль описывает именно отобранные кейсы; он не позволяет ранжировать причины общественной девальвации образования.')
    fig('05_devaluation_bases','Рисунок 6. Основания в девяти кандидатах для качественного анализа девальвации диплома. Каждый эпизод требует дальнейшей проверки исследователем.')
    p('Кейс PK0072 сохраняет значение диплома для формального доступа к работе, одновременно ставя под сомнение его достаточность без практического опыта. В PK0091 противопоставлены реальные умения и формальные документы; критика распространяется на разные уровни подготовки. В PK0285 ценность обучения связывается с собственными усилиями, а наличие документа само по себе не считается гарантией компетентности. Это разные версии критики квалификации, которые нельзя свести к единому отказу от высшего образования.')
